/**
 * Utilitários de texto do motor (sem dependências; rodam no navegador, no
 * Node dos testes e no Deno das Edge Functions).
 */

/** Minúsculas, sem acento e com espaços simples: base de toda comparação. */
export function normalizar(texto) {
  return String(texto ?? "")
    .normalize("NFD")
    .replace(/[̀-ͯ]/g, "")
    .toLowerCase()
    .replace(/[“”"«»]/g, '"')
    .replace(/[‘’]/g, "'")
    .replace(/\s+/g, " ")
    .trim();
}

/** Normalização para conferir citações: ignora pontuação e caixa. */
export function normalizarCitacao(texto) {
  return normalizar(texto)
    .replace(/[^\p{L}\p{N}%$ ]+/gu, " ")
    .replace(/\s+/g, " ")
    .trim();
}

export const palavras = (texto) => normalizar(texto).split(/[^\p{L}\p{N}%]+/u).filter(Boolean);

/** Frases (para citar evidências inteiras, nunca recortes inventados). */
export function frases(texto) {
  return String(texto ?? "")
    .split(/(?<=[.!?…])\s+|\n+/)
    .map((f) => f.trim())
    .filter((f) => f.length > 0);
}

const VAZIAS = new Set(
  "a o as os um uma de da do das dos e em no na nos nas que por para com se eu voce ele ela the and of to in on for is it you i we el la los las y en un una por para con que".split(" "),
);

/** Similaridade de Jaccard entre conjuntos de palavras relevantes (0–1). */
export function similaridade(a, b) {
  const sa = new Set(palavras(a).filter((p) => !VAZIAS.has(p) && p.length > 2));
  const sb = new Set(palavras(b).filter((p) => !VAZIAS.has(p) && p.length > 2));
  if (!sa.size || !sb.size) return 0;
  let comum = 0;
  for (const p of sa) if (sb.has(p)) comum++;
  return comum / (sa.size + sb.size - comum);
}

const MARCAS_IDIOMA = {
  pt: "nao voce eu meu minha uma isso tambem entao porque fiz trabalhei equipe empresa projeto quando onde como foi era tinha estava muito mais com para que de".split(" "),
  en: "the and i my was were have has did worked team company project when where how because with that this our we they it is".split(" "),
  es: "el los las yo mi fue era tenia trabaje equipo empresa proyecto cuando donde como porque con que esto nosotros ellos muy mas pero".split(" "),
};

/**
 * Idioma predominante de uma fala (pt, en ou es), por contagem de palavras
 * funcionais. Devolve { idioma, confianca } — confiança baixa em falas curtas.
 */
export function detectarIdioma(texto) {
  const ps = palavras(texto);
  const pontos = { pt: 0, en: 0, es: 0 };
  for (const p of ps) for (const [lang, lista] of Object.entries(MARCAS_IDIOMA)) if (lista.includes(p)) pontos[lang]++;
  // Desempates comuns pt × es.
  if (/\b(nao|voce|tambem|entao)\b/.test(normalizar(texto))) pontos.pt += 2;
  if (/\b(tambien|usted|entonces|hice|tengo)\b/.test(normalizar(texto))) pontos.es += 2;
  const ordem = Object.entries(pontos).sort((x, y) => y[1] - x[1]);
  const total = ordem.reduce((s, [, v]) => s + v, 0);
  if (!total) return { idioma: null, confianca: 0 };
  const confianca = Math.min(1, (ordem[0][1] - ordem[1][1]) / Math.max(4, total)) * Math.min(1, ps.length / 12);
  return { idioma: ordem[0][0], confianca: Math.round(confianca * 100) / 100 };
}

/** Trecho curto e reconhecível de uma resposta, para retomar na próxima pergunta. */
export function ancora(texto, preferidas = []) {
  const fs = frases(texto);
  if (!fs.length) return "";
  const pref = preferidas.map(normalizar).filter(Boolean);
  let escolhida = fs.find((f) => pref.some((p) => normalizar(f).includes(p))) ?? fs.reduce((a, b) => (b.length > a.length ? b : a));
  escolhida = escolhida.replace(/[.!?…]+$/, "");
  const ws = escolhida.split(/\s+/);
  const limpar = (s) => s.replace(/^[\s,;:–—-]+|[\s,;:–—-]+$/g, "");
  if (ws.length <= 12) return limpar(escolhida);
  // Janela de 10 palavras em torno do termo preferido (ou do início).
  const idx = Math.max(0, ws.findIndex((w) => pref.some((p) => normalizar(w).includes(p.split(" ")[0]))));
  const ini = Math.max(0, Math.min(idx - 3, ws.length - 10));
  return limpar(ws.slice(ini, ini + 10).join(" "));
}

export const contarPalavras = (texto) => palavras(texto).length;

const COMUNS = new Set("Eu Na No Nos Em E O A Os As Um Uma Mas Então Depois Hoje Quando Como Se Isso Esse Essa Foi Era Teve Tinha Por Para Com De Do Da I We The In On At It My Our And But So When Then After Yo En La El Los Las Un Una Pero".split(" "));

/**
 * Tema de uma resposta para retomar na próxima pergunta, como se faz numa
 * conversa ("Ainda sobre o EKS, …"): a palavra-chave da competência que a
 * pessoa usou, ou um termo próprio/técnico (sigla, ferramenta, empresa).
 * Devolve a forma escrita pela pessoa, ou null.
 */
export function topico(texto, palavrasChave = []) {
  const t = String(texto ?? "");
  for (const k of palavrasChave) {
    const m = t.match(new RegExp(`\\b(${k.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")})\\b`, "i"));
    if (m && k.length > 2) return m[1];
  }
  const termos = [...t.matchAll(/(?<![.!?]\s|^)\b([A-Z][A-Za-z0-9+#.-]*[A-Za-z0-9+#])\b/g)].map((m) => m[1]).filter((w) => !COMUNS.has(w) && w.length > 1);
  return termos[0] ?? null;
}
