/**
 * Dossiê em seções de texto (título + parágrafos), sem dependências de
 * navegador: usado na exportação PDF/DOCX e na página pública de leitura.
 */
import { ESTADOS, ROTULO_ETAPA } from "./engine/index.js";

export const mmss = (ms) => {
  const s = Math.max(0, Math.round((ms ?? 0) / 1000));
  return `${String(Math.floor(s / 60)).padStart(2, "0")}:${String(s % 60).padStart(2, "0")}`;
};

/** Seções do dossiê como lista neutra (título + parágrafos), usada pelos dois formatos. */
export function secoes(d) {
  const ind = d.indice;
  return [
    ["Natureza do documento", [d.natureza, `Status: ${d.status === "definitivo" ? "definitivo" : "PARCIAL"}${d.motivosParcial.length ? ` — ${d.motivosParcial.join(" ")}` : ""}`, `Versões: roteiro v${d.versoes.plano ?? "?"} · ${d.versoes.politica} · ${d.versoes.motor} · ${d.versoes.avaliacao}`, d.revisao ? `Revisado por ${d.revisao.por} em ${new Date(d.revisao.em).toLocaleString("pt-BR")}: ${d.revisao.justificativa}` : "Sem revisão humana registrada."]],
    ["Resumo profissional", [d.resumoProfissional || "Não gerado nesta avaliação."]],
    ["Síntese da entrevista", [d.sintese]],
    ["Índice de aderência", [ind.indice == null ? "Sem competências avaliadas." : `${ind.indice}/100 · cobertura ${Math.round(ind.cobertura * 100)}%${ind.suficienteParaComparacao ? "" : " · cobertura insuficiente para comparação"}`, `Fórmula: ${ind.formula}`, ind.aviso]],
    ...d.scorecard.map((c) => [
      `${c.nome} — ${ESTADOS[c.estado]}${c.nivel ? ` · nível ${c.nivel}/4` : ""}${c.revisado ? " (revisado)" : ""}`,
      [
        `Peso ${c.peso} · cobertura ${Math.round(c.cobertura * 100)}% · evidência ${c.suficiencia}${c.autonomia ? ` · ${c.autonomia}` : ""}`,
        c.etapasAusentes.length ? `Não investigado: ${c.etapasAusentes.map((e) => ROTULO_ETAPA[e]).join(", ")}` : null,
        ...c.evidencias.map((e) => `[${mmss(e.ms)} · ${e.turnoId}] "${e.trecho}"${e.etapa ? ` (${ROTULO_ETAPA[e.etapa] ?? e.etapa})` : ""}`),
        ...c.limitacoes.map((l) => `Limitação: ${l}`),
        ...c.pendencias.map((p) => `Pendência: ${p}`),
      ].filter(Boolean),
    ]),
    ["Experiências investigadas", (d.experiencias ?? []).map((e) => `${e.titulo} — contribuição individual: ${e.contribuicaoIndividual}; resultado da equipe: ${e.resultadoDaEquipe}`)],
    ["Conhecimentos técnicos demonstrados", d.conhecimentosTecnicos.map((k) => `${k.tema} (${k.autonomia}) — "${k.trecho}" [${mmss(k.ms)}]`)],
    ["Condições objetivas declaradas", d.condicoesDeclaradas.map((k) => `${k.tema}: "${k.trecho}" [${mmss(k.ms)}]`)],
    ["Idiomas", d.idioma ? [`Idioma do bloco: ${d.idioma.idioma}`, `Declarado: ${d.idioma.declarado ?? "não informado"}`, `Observado: ${d.idioma.observado}`, `Atividades: ${d.idioma.atividades.join("; ")}`, ...d.idioma.evidencias.map((e) => `[${mmss(e.ms)}] "${e.trecho}"`), ...d.idioma.limitacoes] : ["Sem bloco de idioma neste roteiro."]],
    ["Divergências", d.divergencias.map((x) => `Currículo: "${x.curriculo}" × fala: "${x.fala}" — ${x.status === "explicada" ? `explicação registrada: "${x.explicacao}"` : "pendente de esclarecimento"}`)],
    ["Lacunas", d.lacunas],
    ["Dúvidas do candidato encaminhadas", d.duvidasDoCandidato.map((x) => x.texto)],
    ["Perguntas sugeridas para a próxima etapa", d.perguntasSugeridas],
    ["Limitações", d.limitacoes],
  ].map(([t, ps]) => [t, ps.length ? ps : ["—"]]);
}
