/**
 * Dossiê compartilhado por link (somente leitura, com validade). O token vai
 * na URL (?c=) e é conferido pela função interview-sala; cada acesso é
 * registrado na auditoria da empresa.
 */
import { secoes } from "../dossie-texto.js";

const FUNCAO = `${__SUPABASE_URL__}/functions/v1/interview-sala`;
const $ = (id) => document.getElementById(id);
const el = (tag, texto, classe) => Object.assign(document.createElement(tag), { textContent: texto ?? "", className: classe ?? "" });

async function carregar() {
  const c = new URLSearchParams(location.search).get("c") ?? "";
  const regiao = __SUPABASE_REGIAO__ ? `&forceFunctionRegion=${__SUPABASE_REGIAO__}` : "";
  const r = await fetch(`${FUNCAO}?compartilhado=${encodeURIComponent(c)}${regiao}`, { headers: { apikey: __SUPABASE_PUBLISHABLE_KEY__ } });
  const d = await r.json().catch(() => ({}));
  if (!r.ok || !d.ok) {
    $("estado").textContent = d.motivo ?? "Não foi possível abrir o dossiê.";
    return;
  }
  const dossie = d.dossie;
  $("estado").textContent = `Link válido até ${new Date(d.expiraEm).toLocaleString("pt-BR")}. Conteúdo confidencial: não repasse.`;
  $("titulo").textContent = `${dossie.candidato?.nome ?? "Candidato"} · ${dossie.vaga?.cargo ?? ""}`;
  for (const [titulo, ps] of secoes({ ...dossie, transcricao: undefined })) {
    const sec = el("section", "", "card");
    sec.append(el("h2", titulo));
    for (const p of ps) sec.append(el("p", p));
    $("dossie").append(sec);
  }
  if (dossie.transcricao) {
    const det = el("details", "", "card");
    det.append(el("summary", "Transcrição"));
    for (const t of dossie.transcricao) det.append(el("p", `${t.papel === "ia" ? "Entrevistadora (IA)" : "Candidato"}: ${t.texto}`));
    $("dossie").append(det);
  }
}
carregar();
